-- chat schema — owned by chat-svc (SOC-3a, ADR-049 addendum 2026-10-30): end-to-end encrypted messaging.
-- The server stores public device keys and ciphertext only; it never sees message plaintext or private keys.
-- Model (Matrix-style, vodozemac): every conversation, DIRECT or GROUP, is encrypted once per message with a
-- Megolm session; Megolm session keys reach each recipient device in Olm-encrypted to-device messages.
-- IDs are UUIDv7 (ADR-010); device ids are generated by the client (it signs them). No cross-schema FKs (ADR-007).

CREATE SCHEMA IF NOT EXISTS chat;

-- One row per browser installation that registered E2EE keys. Removed devices keep their row (deleted_at) so
-- messages still name their sender device; their one-time keys and pending to-device messages are deleted.
CREATE TABLE chat.devices (
    id                 uuid PRIMARY KEY,                -- generated and signed by the client
    user_id            uuid NOT NULL,
    display_name       text NOT NULL,                   -- e.g. "Chrome trên Windows", shown to the owner only
    curve25519_key     text NOT NULL,                   -- identity key, unpadded base64
    ed25519_key        text NOT NULL,                   -- signing key, unpadded base64
    signature          text NOT NULL,                   -- ed25519 over the canonical device-keys JSON
    fallback_key_id    text,                            -- used when one-time keys run out
    fallback_key       text,
    fallback_signature text,
    created_at         timestamptz NOT NULL DEFAULT now(),
    last_seen_at       timestamptz NOT NULL DEFAULT now(),
    deleted_at         timestamptz,
    CONSTRAINT devices_display_name CHECK (char_length(display_name) BETWEEN 1 AND 64),
    CONSTRAINT devices_keys CHECK (char_length(curve25519_key) = 43 AND char_length(ed25519_key) = 43
                                   AND char_length(signature) = 86),
    CONSTRAINT devices_fallback CHECK ((fallback_key_id IS NULL) = (fallback_key IS NULL)
                                       AND (fallback_key IS NULL) = (fallback_signature IS NULL))
);
-- An identity key belongs to exactly one device, ever.
CREATE UNIQUE INDEX devices_curve25519 ON chat.devices (curve25519_key);
CREATE INDEX devices_user_active ON chat.devices (user_id, created_at) WHERE deleted_at IS NULL;

-- Signed one-time keys; a claim deletes exactly one (SELECT … FOR UPDATE SKIP LOCKED, then DELETE).
CREATE TABLE chat.one_time_keys (
    device_id  uuid NOT NULL REFERENCES chat.devices (id) ON DELETE CASCADE,
    key_id     text NOT NULL,
    public_key text NOT NULL,
    signature  text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (device_id, key_id),
    CONSTRAINT one_time_keys_shape CHECK (char_length(key_id) BETWEEN 1 AND 64
                                          AND char_length(public_key) = 43 AND char_length(signature) = 86)
);

CREATE TYPE chat.conversation_kind AS ENUM ('DIRECT', 'GROUP');

CREATE TABLE chat.conversations (
    id              uuid PRIMARY KEY,
    kind            chat.conversation_kind NOT NULL,
    title           text,                                   -- GROUP only (metadata, not encrypted)
    created_by      uuid NOT NULL,
    direct_key      text,                                   -- DIRECT only: "<smaller uuid>:<larger uuid>"
    last_seq        bigint NOT NULL DEFAULT 0,              -- seq of the newest message; bumped per message
    last_message_at timestamptz,
    created_at      timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT conversations_direct_key CHECK ((kind = 'DIRECT') = (direct_key IS NOT NULL)),
    CONSTRAINT conversations_title CHECK (
        (kind = 'DIRECT' AND title IS NULL) OR (kind = 'GROUP' AND title IS NOT NULL AND char_length(title) BETWEEN 1 AND 80)),
    CONSTRAINT conversations_last_seq CHECK (last_seq >= 0)
);
-- At most one DIRECT conversation per pair of users.
CREATE UNIQUE INDEX conversations_direct ON chat.conversations (direct_key) WHERE direct_key IS NOT NULL;

CREATE TYPE chat.member_role AS ENUM ('OWNER', 'ADMIN', 'MEMBER');
-- REQUESTED: added by someone the user does not follow; sees the conversation under "requests" until they
-- accept (ACTIVE) or decline (LEFT). LEFT: left, removed or declined.
CREATE TYPE chat.member_state AS ENUM ('ACTIVE', 'REQUESTED', 'LEFT');

CREATE TABLE chat.members (
    conversation_id uuid NOT NULL REFERENCES chat.conversations (id) ON DELETE CASCADE,
    user_id         uuid NOT NULL,
    role            chat.member_role NOT NULL DEFAULT 'MEMBER',
    state           chat.member_state NOT NULL,
    joined_seq      bigint NOT NULL,           -- first seq this member may fetch (last_seq + 1 when added)
    left_seq        bigint,                    -- last seq still fetchable after leaving; NULL while not LEFT
    last_read_seq   bigint NOT NULL DEFAULT 0,
    muted_until     timestamptz,
    created_at      timestamptz NOT NULL DEFAULT now(),
    updated_at      timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (conversation_id, user_id),
    CONSTRAINT members_left CHECK ((state = 'LEFT') = (left_seq IS NOT NULL)),
    CONSTRAINT members_seqs CHECK (joined_seq >= 1 AND last_read_seq >= 0)
);
CREATE INDEX members_user ON chat.members (user_id, state, conversation_id);

CREATE TYPE chat.message_kind AS ENUM ('ENCRYPTED', 'SYSTEM');

-- ENCRYPTED: Megolm ciphertext from a member device. SYSTEM: written by chat-svc on membership or title
-- changes (plaintext JSON in system_body; clients rotate their Megolm session on member changes).
CREATE TABLE chat.messages (
    conversation_id   uuid NOT NULL REFERENCES chat.conversations (id) ON DELETE CASCADE,
    seq               bigint NOT NULL,
    id                uuid NOT NULL,
    kind              chat.message_kind NOT NULL,
    sender_id         uuid,                    -- NULL for SYSTEM (the actor is in system_body)
    sender_device_id  uuid,                    -- NULL for SYSTEM
    client_msg_id     uuid,                    -- idempotency key chosen by the sender; NULL for SYSTEM
    megolm_session_id text,
    ciphertext        text,                    -- NULL once deleted (tombstone) and for SYSTEM
    system_body       jsonb,
    deleted_at        timestamptz,
    created_at        timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (conversation_id, seq),
    CONSTRAINT messages_shape CHECK (
        (kind = 'ENCRYPTED' AND sender_id IS NOT NULL AND sender_device_id IS NOT NULL AND client_msg_id IS NOT NULL
             AND megolm_session_id IS NOT NULL AND system_body IS NULL
             AND (ciphertext IS NOT NULL OR deleted_at IS NOT NULL))
        OR (kind = 'SYSTEM' AND sender_id IS NULL AND sender_device_id IS NULL AND client_msg_id IS NULL AND ciphertext IS NULL
             AND system_body IS NOT NULL)),
    CONSTRAINT messages_ciphertext_size CHECK (ciphertext IS NULL OR char_length(ciphertext) <= 87384) -- 64 KiB
);
CREATE UNIQUE INDEX messages_id ON chat.messages (id);
CREATE UNIQUE INDEX messages_idempotency ON chat.messages (sender_id, client_msg_id) WHERE client_msg_id IS NOT NULL;

-- Olm-encrypted messages addressed to one device (Megolm session keys, key requests). Deleted when the
-- recipient acknowledges them, when the device is removed, or after 30 days.
CREATE TABLE chat.to_device (
    id                  bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    recipient_device_id uuid NOT NULL REFERENCES chat.devices (id) ON DELETE CASCADE,
    sender_id           uuid NOT NULL,
    sender_device_id    uuid NOT NULL,
    ciphertext          text NOT NULL,
    created_at          timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT to_device_size CHECK (char_length(ciphertext) <= 21848)               -- 16 KiB
);
CREATE INDEX to_device_recipient ON chat.to_device (recipient_device_id, id);
CREATE INDEX to_device_created ON chat.to_device (created_at);
